_KEYS = sorted(INFO, key=len, reverse=True)


def explain(label_name):
    """Return {'key','what','means','watch'} for a label name, or None if unknown."""
    n = label_name.lower()
    for k in _KEYS:
        if k in n:
            w, m, c = INFO[k]
            return {"key": k, "what": w, "means": m, "watch": c}
    return None
